1	// Edinburgh Festival Fringe show pages:
2	// https://www.edfringe.com/tickets/whats-on/<slug>
3	//
4	// A Next.js app: there's no JSON-LD or server-rendered <h1>/<time> markup,
5	// but every page embeds its data as JSON in:
6	//
7	//   <script id="__NEXT_DATA__" type="application/json">
8	//     { "props": { "pageProps": { "data": { "event": {
9	//       "title": "Sophie Duker: Hot Beef Injection",
10	//       "description": "...",
11	//       "duration": 60,
12	//       "venues": [ { "title": "Pleasance Courtyard",
13	//                      "address1": "60 Pleasance", "postCode": "EH8 9TJ" } ],
14	//       "spaces": [ { "venueName": "Forth at Pleasance Courtyard" } ],
15	//       "performances": [
16	//         { "dateTime": "2026-08-05T19:30:00.000Z",
17	//           "estimatedEndDateTime": "2026-08-05T21:00:00.000Z" },
18	//         ... one entry per performance ...
19	//       ]
20	//     } } } } }
21	//   </script>
22	//
23	// Where each field comes from:
24	//   title               event.title
25	//   start/end           the first performance's dateTime/estimatedEndDateTime
26	//                       (already exact UTC instants)
27	//   eventLengthInMinutes event.duration (minutes, same for every performance)
28	//   location            the space's venueName (more specific than the venue name
29	//                       alone, e.g. "Forth at Pleasance Courtyard") plus the
30	//                       venue's address and postcode
31	//   description         event.description
32	//
33	// A show usually runs on most days of the festival; we surface the first
34	// performance as the event. Every Fringe show runs in Edinburgh, so `ctz` is
35	// always "GB" — even on pages where the event JSON couldn't be found.
36	(() => {
37	  const { clean, jsonScript, parts } = GCal;
38	
39	  function readEvent() {
40	    const next = jsonScript("#__NEXT_DATA__");
41	    const data = next && next.props && next.props.pageProps && next.props.pageProps.data;
42	    return (data && data.event) || null;
43	  }
44	
45	  function flattenLocation(event) {
46	    const venue = (event.venues || [])[0];
47	    const space = (event.spaces || [])[0];
48	    // Case-sensitive de-dup: these are proper names/postcodes, not address
49	    // fragments that repeat with different casing.
50	    const loc = parts((a, b) => a === b);
51	    loc.add((space && space.venueName) || (venue && venue.title));
52	    if (venue) loc.add(venue.address1).add(venue.address2).add(venue.postCode);
53	    return loc.join();
54	  }
55	
56	  GCal.sources.push({
57	    name: "edinburghfringe",
58	    matches: (host) => /(^|\.)edfringe\.com$/.test(host),
59	    extract() {
60	      const event = readEvent();
61	      if (!event) return { ctz: "GB" };
62	
63	      const loc = flattenLocation(event);
64	      const t = clean(event.title);
65	      const performances = event.performances || [];
66	
67	      const eventLengthInMinutes = event.duration ? +event.duration : null;
68	
69	      if (!performances.length) {
70	        return { title: t, start: "", end: null, location: loc, description: clean(event.description), ctz: "GB", eventLengthInMinutes };
71	      }
72	
73	      return {
74	        events: performances.map((p) => ({
75	          title: t,
76	          start: p.dateTime || "",
77	          end: p.estimatedEndDateTime || null,
78	          location: loc,
79	          eventLengthInMinutes,
80	        })),
81	        description: clean(event.description),
82	        ctz: "GB",
83	      };
84	    },
85	  });
86	})();
