217	    const startMin = +sm[2] * 60 + +sm[3];
218	    const re = new RegExp(`(${TIME})\\s*(?:to|until|till|[-–—])\\s*(${TIME})`, "ig");
219	    let m;
220	    while ((m = re.exec(GCal.clean(text)))) {
221	      const a = timeToMinutes(m[1]);
222	      const b = timeToMinutes(m[2]);
223	      if (a == null || b == null || a !== startMin) continue;
224	      const date = b <= a ? nextDay(sm[1]) : sm[1];
225	      return `${date}T${pad(Math.floor(b / 60))}:${pad(b % 60)}:00`;
226	    }
227	    return "";
228	  }
229	
230	  // A start–end pair that covers WHOLE CALENDAR DAYS — midnight through 23:59
231	  // (or 23:59:59) — is how a great many CMS/event platforms express an all-day
232	  // event: SharePoint, Drupal and the common WordPress event plugins all export
233	  // "00:00:00" → "23:59:00" for one, as do the municipal/museum listing sites
