243	  function allDayRange(start, end) {
244	    const s = /^(\d{4}-\d{2}-\d{2})T00:00(?::00)?$/.exec(GCal.clean(start));
245	    const e = /^(\d{4}-\d{2}-\d{2})T23:59(?::00|:59)?$/.exec(GCal.clean(end));
