1	// comy.co.il event pages: https://comy.co.il/event/adir-miller/
2	//
3	// A WordPress ticketing site for touring shows (mostly standup/comedy). Each
4	// page is a single ARTIST/SHOW with a list of tour dates, one per venue — not a
5	// single-occurrence event. No schema.org Event JSON-LD; every field is read
6	// from the DOM.
7	//
8	//   title       "<h1> <h2>" inside ".te-details" — the show name (h1, e.g.
9	//               "אדיר מילר") followed by its genre/subtitle (h2, e.g.
10	//               "סטנדאפ") -> "אדיר מילר סטנדאפ". Scoped to ".te-details": a
11	//               site-wide accessibility-toolbar widget injects its OWN
12	//               <h2>תפריט נגישות</h2> ("accessibility menu") earlier in the DOM,
13	//               so a bare "h2" query would grab that instead. Same title for
14	//               every performance, so telavivcinematheque-style grouping
15	//               (assemble-events.js) folds all instances into one event.
16	//   events      one entry per `#events .single-page-event` tour date:
17	//                 date    ".date" div, "DD.MM" with NO YEAR (e.g. "28.07")
18	//                 time    ".single-light" span, "<weekday> HH:MM" (e.g.
19	//                         "יום ג' 21:45") — only the trailing clock time is read
20	//                 venue   ".single-place-string" (venue name only, no address)
21	//               The year isn't on each row, but the page header states the tour's
22	//               overall date range ("28/07/2026 - 16/12/2026" in ".te-date"); we
23	//               seed the running year from that range's first date and roll it
24	//               forward whenever a row's month is lower than the previous row's
25	//               (the listing is chronological), so a tour spanning a New Year's
26	//               boundary still gets each date's correct year.
27	//   description the ".te-details" teaser block: the show name/genre again, the
28	//               blurb paragraph, the photo-credit line, and the ticket-source
29	//               disclaimer — everything in that block except the date-range and
30	//               price rows (read separately above).
31	//   ctz         always "Asia/Jerusalem" — comy.co.il is an Israeli ticketing
32	//               site; every venue it lists is in Israel.
33	(() => {
34	  const { clean, text } = GCal;
35	
36	  // The tour's overall date range is stated once, in the page header
37	  // (".te-date", e.g. "28/07/2026 - 16/12/2026"); read its first date's year as
38	  // the starting point for the per-row "DD.MM" dates below, which carry no year
39	  // of their own.
40	  function headerStartYear() {
41	    const m = clean(text(".te-date")).match(/(\d{2})\/(\d{2})\/(\d{4})/);
42	    return m ? +m[3] : GCal.now().getFullYear();
43	  }
44	
45	  // The teaser block above the tour-date list: the show name/genre, blurb,
46	  // photo credit and ticket-source disclaimer. Read every direct child's text
47	  // except the date-range and price rows, which are handled separately (and
48	  // would otherwise leak the "28/07/2026 - 16/12/2026" row into the description).
49	  function description(wrap) {
50	    if (!wrap) return "";
51	    return [...wrap.childNodes]
52	      .filter((n) => !(n.nodeType === 1 && (n.classList.contains("te-date") || n.classList.contains("ticket-price"))))
53	      .map((n) => clean(n.textContent))
54	      .filter(Boolean)
55	      .join("\n");
56	  }
57	
58	  // One tour date per `.single-page-event` row: "DD.MM" (no year) + a weekday
59	  // + "HH:MM" clock time + a venue name. Rows are listed chronologically, so the
60	  // running `year` (seeded from the page header) only advances when a row's
61	  // month drops below the previous row's — i.e. the tour crossed a New Year.
62	  function performances(title) {
63	    let year = headerStartYear();
64	    let prevMonth = 0;
65	    return [...document.querySelectorAll("#events .single-page-event")]
66	      .map((el) => {
67	        const dm = clean(text(".date", el)).match(/(\d{2})\.(\d{2})/);
68	        const venue = clean(text(".single-place-string", el));
69	        if (!dm || !venue) return null;
70	        const [, dd, mm] = dm;
71	        if (+mm < prevMonth) year++;
72	        prevMonth = +mm;
73	        const tm = clean(text(".single-light", el)).match(/(\d{1,2}):(\d{2})/);
